/**
 * The PNG encoder behind 保存到相册. It is pure JS, so the tests decode the
 * generated bytes with upng-js and then scan the decoded pixels with jsqr —
 * the same pipeline as 图片解析二维码. That proves the file is a real PNG and
 * that the code in it is scannable, not just that the function returned a
 * string.
 */
import {describe, expect, it} from '@jest/globals';
import UPNG from 'upng-js';

import {encodeQr} from '../src/qr/qrCode';
import {decodeQrFromBase64} from '../src/qr/imageDecode';
import {qrModulePixels, qrPngBase64, qrPngBytes} from '../src/qr/qrPng';
import {qrSaveTitle} from '../src/native/imageSave';

const VALUE = 'https://example.com';

function codeFor(value: string = VALUE) {
  const result = encodeQr(value, 'M');
  if (!result.ok) {
    throw new Error(`expected a matrix, got: ${result.error}`);
  }
  return result.code;
}

function pngOf(value: string = VALUE) {
  const code = codeFor(value);
  const bytes = qrPngBytes(code, {modulePixels: 6});
  return {
    code,
    bytes,
    decoded: UPNG.decode(
      bytes.buffer.slice(
        bytes.byteOffset,
        bytes.byteOffset + bytes.byteLength,
      ) as ArrayBuffer,
    ),
  };
}

describe('qrPngBytes', () => {
  it('starts with the PNG signature and ends with IEND', () => {
    const {bytes} = pngOf();

    expect(Array.from(bytes.subarray(0, 8))).toEqual([
      0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a,
    ]);
    expect(
      Array.from(bytes.subarray(bytes.length - 8, bytes.length - 4)).map(byte =>
        String.fromCharCode(byte),
      ),
    ).toEqual(['I', 'E', 'N', 'D']);
  });

  it('is a grayscale PNG of the quiet zone plus the matrix', () => {
    const {code, decoded} = pngOf();
    const side = (code.size + 8) * 6;

    expect(decoded.width).toBe(side);
    expect(decoded.height).toBe(side);
  });

  it('draws the four-module quiet zone white and the finder pattern black', () => {
    const {decoded} = pngOf();
    const rgba = new Uint8Array(UPNG.toRGBA8(decoded)[0]);
    const stride = decoded.width * 4;

    const pixel = (x: number, y: number): number => rgba[y * stride + x * 4];

    // The first quiet-zone module stays white at every corner.
    for (const [x, y] of [
      [0, 0],
      [decoded.width - 1, 0],
      [0, decoded.height - 1],
      [decoded.width - 1, decoded.height - 1],
    ]) {
      expect(pixel(x, y)).toBe(255);
    }

    // The top-left finder pattern's outer ring starts at (4, 4) modules.
    expect(pixel(4 * 6, 4 * 6)).toBe(0);
    expect(pixel(4 * 6 + 3 * 6, 4 * 6)).toBe(0);
  });

  it('encodes a PNG that jsqr reads back as the original text', () => {
    const base64 = qrPngBase64(codeFor(), {modulePixels: 6});

    // Same base64 -> pixel -> jsqr path the app uses for picked images.
    expect(decodeQrFromBase64(base64)).toEqual({ok: true, value: VALUE});
  });

  it('encodes a unicode value the same way', () => {
    const value = 'KMP RN QR 测试 2026';
    const base64 = qrPngBase64(codeFor(value), {modulePixels: 6});

    expect(decodeQrFromBase64(base64)).toEqual({ok: true, value});
  });

  it('rejects an inconsistent matrix instead of drawing a broken code', () => {
    const code = codeFor();
    const broken = {...code, modules: code.modules.slice(0, 10)};

    expect(() => qrPngBytes(broken)).toThrow('二维码矩阵不完整');
  });

  it('rejects a non-positive module size', () => {
    expect(() => qrPngBytes(codeFor(), {modulePixels: 0})).toThrow(
      '每模块像素数无效',
    );
  });
});

describe('qrModulePixels', () => {
  it('keeps a small code at the sharp end of the range', () => {
    expect(qrModulePixels(25)).toBe(12);
  });

  it('shrinks a version-40 code so the bridge carries a reasonable payload', () => {
    const pixels = qrModulePixels(177);

    expect(pixels).toBeGreaterThanOrEqual(3);
    expect((177 + 8) * pixels).toBeLessThanOrEqual(800);
  });

  it('never goes below three pixels per module', () => {
    expect(qrModulePixels(400)).toBe(3);
  });
});

describe('qrSaveTitle', () => {
  it('is a createAsset-safe, timestamped name', () => {
    const title = qrSaveTitle(new Date(2026, 10, 17, 9, 5, 3));

    expect(title).toBe('KMP-RN-QR-20261117-090503');
    // None of the characters createAsset rejects may appear.
    for (const character of [
      '\\',
      '/',
      ':',
      '*',
      '?',
      '"',
      "'",
      '`',
      '<',
      '>',
      '|',
      '{',
      '}',
      '[',
      ']',
    ]) {
      expect(title).not.toContain(character);
    }
  });
});
